  /* ── Bedside Tool 2: Acute Asthma & IV MgSO4 Weight-Based Dose Calculator ── */
  showDoseCalcModal() {
    const html = `
      <div class="dose-calc-form">
        <div class="dose-input-group">
          <label for="weight-input">Child's Weight (kg)</label>
          <div class="dose-input">
            <input type="number" id="weight-input" placeholder="e.g. 22" min="4" max="80" step="0.5">
            <span>kg</span>
          </div>
        </div>
        <button class="dose-calc-btn" id="calc-dose-btn">Calculate Golden-Hour Asthma Doses</button>
        <div class="dose-result" id="dose-result">
          <div class="dose-result-title">&#9745; GINA 2026 &amp; IAP Golden-Hour Emergency Doses</div>
          <div class="dose-drug">
            <div>
              <div class="dose-drug-name">Inhaled Salbutamol (SABA) — First Hour (q20min &times; 3)</div>
              <div class="dose-drug-detail">pMDI+Spacer: 4–10 puffs (100 mcg/puff) | Nebulizer: 2.5 mg (&lt;20 kg) or 5 mg (&ge;20 kg)</div>
            </div>
            <div>
              <div class="dose-amount" id="salb-dose">—</div>
              <span class="dose-amount-unit">per dose q20m</span>
            </div>
          </div>
          <div class="dose-drug">
            <div>
              <div class="dose-drug-name">Inhaled Ipratropium Bromide — Add for Moderate/Severe</div>
              <div class="dose-drug-detail">250 mcg (&lt;20 kg) or 500 mcg (&ge;20 kg) every 20 min &times; 3 doses in Hour 1 [Ref 23]</div>
            </div>
            <div>
              <div class="dose-amount" id="ipra-dose">—</div>
              <span class="dose-amount-unit">mcg q20m &times; 3</span>
            </div>
          </div>
          <div class="dose-drug">
            <div>
              <div class="dose-drug-name">Oral Prednisolone (Within 60 Min) OR Oral Dexamethasone</div>
              <div class="dose-drug-detail">Prednisolone 1–2 mg/kg/d (max 40 mg) &times; 3–5d | Dexa 0.6 mg/kg (max 16 mg) &times; 1–2d [Ref 24]</div>
            </div>
            <div>
              <div class="dose-amount" id="pred-dose">—</div>
              <span class="dose-amount-unit">PO within 1 hr</span>
            </div>
          </div>
          <div class="dose-drug">
            <div>
              <div class="dose-drug-name">IV Magnesium Sulfate (MgSO&#8324;) — Hour-1 Refractory Rescue</div>
              <div class="dose-drug-detail">40–50 mg/kg (max 2,000 mg) diluted in Normal Saline infused over 20–30 min [Ref 25]</div>
            </div>
            <div>
              <div class="dose-amount" id="mg-dose">—</div>
              <span class="dose-amount-unit">mg IV over 25 min</span>
            </div>
          </div>
          <div class="dose-warning">
            &#9888; <strong>CRITICAL SAFETY RULES [Ref 1, 8, 9]:</strong><br>
            &bull; Maintain target <strong>SpO&#8322; 92–95% (GINA 2026 target for 6–17y; >=92% for <=5y)</strong> with controlled oxygen.<br>
            &bull; <strong>NEVER give Sedatives</strong> (Midazolam/Diazepam/Promethazine) — causes fatal respiratory arrest.<br>
            &bull; <strong>NEVER prescribe Oral Salbutamol Syrups</strong> or routine antibiotics.<br>
            &bull; Infuse IV MgSO&#8324; slowly over <strong>20–30 minutes</strong> (never rapid push — risks hypotension/bradycardia).
          </div>
        </div>
      </div>
    `;
    this.showModal('Acute Asthma &amp; IV MgSO&#8324; Dose Calculator — GINA 2026 / IAP', html);

    setTimeout(() => {
      const btn = document.getElementById('calc-dose-btn');
      const inp = document.getElementById('weight-input');
      if (!btn || !inp) return;
      const calc = () => {
        const wt = parseFloat(inp.value);
        if (!wt || wt < 4 || wt > 80) {
          inp.style.borderColor = '#ef4444';
          return;
        }
        inp.style.borderColor = '';
        const salbNeb = wt < 20 ? '2.5 mg Neb (or 4–6 puffs Spacer)' : '5.0 mg Neb (or 6–10 puffs Spacer)';
        const ipra = wt < 20 ? '250' : '500';
        const pred = Math.round(Math.min(wt * 1.5, 40));
        const dexa = (Math.min(wt * 0.6, 16)).toFixed(1);
        const mgLow = Math.round(Math.min(wt * 40, 2000));
        const mgHigh = Math.round(Math.min(wt * 50, 2000));

        document.getElementById('salb-dose').textContent = salbNeb;
        document.getElementById('ipra-dose').textContent = ipra;
        document.getElementById('pred-dose').textContent = `Pred ${pred} mg (or Dexa ${dexa} mg)`;
        document.getElementById('mg-dose').textContent = `${mgLow}–${mgHigh}`;
        document.getElementById('dose-result').classList.add('visible');
      };
      btn.addEventListener('click', calc);
      inp.addEventListener('keydown', e => { if (e.key === 'Enter') calc(); });
    }, 100);
  }

